mapper.select:
SELECT * FROM ( SELECT rownum rnum, a.* FROM ( SELECT PROD_ID as prodId, PROD_CODE as prodCode, PROD_NAME as name, PROD_PRICE as price, IMAGE_URL as imageUrl, ORIGIN_URL as originUrl, SOURCE as communityName, BOARD_TYPE as boardType, REG_DATE as regDate FROM Common_Product WHERE 1=1
AND PROD_NAME LIKE '%'||#{keyword}||'%' AND PROD_CODE = #{keyword}
ORDER BY REG_DATE DESC ) a WHERE rownum <= #{pageEnd} ) WHERE rnum >= #{pageStart}
